@dataclass
class Request:
    method: str
    path: str
    token: str | None
    json: dict


def handle(request: Request) -> tuple[int, dict]:
    if request.method == "GET" and request.path == "/v1/items":
        return 200, {"items": []}
    return 404, {"error": "not_found"}

