import json


def create_order(connection, order_id, customer, items):
    connection.execute(
        "INSERT INTO orders(id, customer, items_json) VALUES (?, ?, ?)",
        (order_id, customer, json.dumps(items, sort_keys=True)),
    )


def read_order(connection, order_id):
    row = connection.execute(
        "SELECT id, customer, items_json FROM orders WHERE id = ?", (order_id,)
    ).fetchone()
    return {"id": row[0], "customer": row[1], "items": json.loads(row[2])}

def build_report(rows):
    report = []
    for row in rows:
        count = sum(1 for candidate in rows if candidate["group"] == row["group"])
        report.append({"id": row["id"], "group": row["group"], "group_count": count})
    return report


def generated_rows(size):
    return [{"id": index, "group": f"g-{index % 25}"} for index in range(size)]
